import ast

class BasitLinter(ast.NodeVisitor):
    def __init__(self):
        self.bulgular = []

    def visit_ExceptHandler(self, dugum):
        if dugum.type is None:
            self.bulgular.append("satir {}: ciplak except".format(dugum.lineno))
        self.generic_visit(dugum)

    def visit_FunctionDef(self, dugum):
        for v in dugum.args.defaults:
            if isinstance(v, (ast.List, ast.Dict, ast.Set)):
                self.bulgular.append("satir {}: degistirilebilir varsayilan".format(dugum.lineno))
        self.generic_visit(dugum)

kaynak = "def ekle(x, liste=[]):\n    try:\n        liste.append(int(x))\n    except:\n        pass\n    return liste\n"
linter = BasitLinter()
linter.visit(ast.parse(kaynak))
for b in linter.bulgular:
    print(b)
print("toplam bulgu:", len(linter.bulgular))

