```python
import datetime
AYAR = {"limit": 20.0}

def islem(l, t=1, y=0, m=None):
    r = []
    tp = 0
    for x in l:
        try:
            g = (datetime.date.today() - x[2]).days
            if g > 0:
                if t == 1:
                    c = g * 0.5
                elif t == 2:
                    c = g * 1.0
                else:
                    c = g * 0.25
                if c > AYAR["limit"]:
                    c = AYAR["limit"]
                tp = tp + c
                r.append(x[0] + ": " + str(c))
        except:
            pass
    if y == 1:
        print("\n".join(r))
    if m is not None:
        open(m, "w").write(str(tp))
    return tp
```
